/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  console.log(getResult(line));
});

function getResult(str) {
  // 对字符串进行备份
  const back_str = str;

  // 压缩字符串str只能包含小写字母和数字，如果包含其他字符则非法
  if (/[^a-z0-9]/.test(str)) {
    return "!error";
  }

  // 该正则用于匹配 “4a”，“12b” 这种 “数字+小写字母” 的子串
  const regExp = /(\d+)([a-z])?/g;

  while (true) {
    const res = regExp.exec(str);

    if (!res) break;

    // 要被替换的压缩子串
    const src = res[0];

    const repeat_times = res[1] - 0;

    // 压缩字符串中不会存在0，1，2
    if (repeat_times <= 2) {
      return "!error";
    }

    const repeat_content = res[2];
    // abc4这种情况视为异常
    if (!repeat_content) return "!error";

    // // 替换后的解压子串
    const tar = new Array(repeat_times).fill(repeat_content).join("");

    str = str.replace(src, tar);
  }

  // 如果解压字符串重新压缩后，和输入的压缩子串不一样，则说明输入的压缩字符串不合法，比如输入为3bb，bbb, 3b4b都是不合法
  if (zip(str) != back_str) return "!error";

  return str;
}

// 压缩字符串
function zip(str) {
  str += "-";

  const ans = [];

  const stack = [];
  let repeat = 0;

  for (let c of str) {
    if (stack.length == 0) {
      stack.push(c);
      repeat++;
      continue;
    }

    // stack.length > 0
    const top = stack.at(-1);
    if (top == c) {
      repeat++;
      continue;
    }

    // top != c
    if (repeat > 2) {
      ans.push(`${repeat}${top}`);
    } else {
      ans.push(...new Array(repeat).fill(top));
    }
    stack.length = 0;
    stack.push(c);
    repeat = 1;
  }

  return ans.join("");
}

